import React, {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";

import useSessionKey from "../utils/useSessionKey";
import { getAuthSnapshot } from "../utils/authState";
const SavedPlacesContext = createContext(null);

const getPlaceId = (place) => place?.id ?? place?.placeId;

export const SavedPlacesProvider = ({ children }) => {
  const accountKey = useSessionKey();
  const [records, setRecords] = useState({ accountKey, places: [] });
  const savedPlaces = useMemo(() => records.accountKey === accountKey ? records.places : [], [records, accountKey]);
  const setSavedPlaces = useCallback(update => {
    if (getAuthSnapshot().accountKey !== accountKey) return;
    setRecords(previous => {
      const places = previous.accountKey === accountKey ? previous.places : [];
      return { accountKey, places: typeof update === "function" ? update(places) : update };
    });
  }, [accountKey]);

  const isSaved = useCallback(
    (id) => {
      if (id === null || id === undefined) return false;

      return savedPlaces.some(
        (place) => String(getPlaceId(place)) === String(id),
      );
    },
    [savedPlaces],
  );

  const addSavedPlace = useCallback((place) => {
    const placeId = getPlaceId(place);

    if (placeId === null || placeId === undefined) return;

    setSavedPlaces((prev) => {
      const exists = prev.some(
        (item) => String(getPlaceId(item)) === String(placeId),
      );

      if (exists) return prev;

      return [...prev, place];
    });
  }, [setSavedPlaces]);

  const removeSavedPlace = useCallback((id) => {
    if (id === null || id === undefined) return;

    setSavedPlaces((prev) =>
      prev.filter((place) => String(getPlaceId(place)) !== String(id)),
    );
  }, [setSavedPlaces]);

  const toggleSavedPlace = useCallback(
    (place) => {
      const placeId = getPlaceId(place);

      if (placeId === null || placeId === undefined) return;

      if (isSaved(placeId)) {
        removeSavedPlace(placeId);
        return;
      }

      addSavedPlace(place);
    },
    [isSaved, addSavedPlace, removeSavedPlace],
  );

  const clearSavedPlaces = useCallback(() => {
    setSavedPlaces([]);
  }, [setSavedPlaces]);

  const syncSavedPlaces = useCallback((places, complete = false) => {
    setSavedPlaces(previous => complete ? places : [...new Map([...previous, ...places].map(place => [String(getPlaceId(place)), place])).values()]);
  }, [setSavedPlaces]);

  const value = useMemo(
    () => ({
      savedPlaces,
      isSaved,
      addSavedPlace,
      removeSavedPlace,
      toggleSavedPlace,
      clearSavedPlaces,
      syncSavedPlaces,
    }),
    [
      savedPlaces,
      isSaved,
      addSavedPlace,
      removeSavedPlace,
      toggleSavedPlace,
      clearSavedPlaces,
      syncSavedPlaces,
    ],
  );

  return (
    <SavedPlacesContext.Provider value={value}>
      {children}
    </SavedPlacesContext.Provider>
  );
};

export const useSavedPlaces = () => {
  const context = useContext(SavedPlacesContext);

  if (!context) {
    throw new Error("useSavedPlaces must be used within SavedPlacesProvider");
  }

  return context;
};
